 "content": "def transform(grid):
    """Downsample by 3, retaining the non-background marker in each block."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            counts = {}
            for r in range(3 * br, 3 * br + 3):
                for c in range(3 * bc, 3 * bc + 3):
                    value = grid[r][c]
                    if value not in (0, 5):
                        counts[value] = counts.get(value, 0) + 1
            if counts:
                out[br][bc] = max(counts, key=counts.get)
    return out

